import { useEffect, useState } from "react";
import MapaMexico from "./MapaMexico";
import { useTheme } from "./useTheme";
import "./components/Inicio.css";

function Inicio() {
  const [sismos, setSismos] = useState([]); // Almacena todos los sismos
  const [menuVisible, setMenuVisible] = useState(false); // Muestra / Oculta el menú lateral
  const [sismoSeleccionado, setSismoSeleccionado] = useState(null); // Guarda el sismo seleccionado
  const [coordenadas, setCoordenadas] = useState(null); // Coordenadas para centrar el mapa en un sismo
  const { theme, toggleTheme } = useTheme(); // Para alternar entre el tema claro y oscuro

  // Estados para los filtros
  const [fechaFiltro, setFechaFiltro] = useState(""); // Campo de filtro de fecha
  const [magnitudFiltro, setMagnitudFiltro] = useState(""); // Campo de filtro de magnitud
  const [noResults, setNoResults] = useState(false); // Estado para mostrar mensaje cuando no hay resultados

  // Efecto para obtener datos al cargar la página
  useEffect(() => {
    fetch("http://localhost:9090/inicio") // URL de tu backend
      .then((response) => {
        if (!response.ok) throw new Error("Error en la respuesta del servidor");
        return response.json();
      })
      .then((data) => {
        setSismos(data); // Guarda los sismos obtenidos en el estado
      })
      .catch((error) => {
        console.error("Error al obtener datos:", error);
      });
  }, []);

  // Función para manejar el clic en un sismo del menú lateral
  const handleSismoClick = (sismo) => {
    setSismoSeleccionado(sismo);
    setCoordenadas({ lat: sismo.latitud, lng: sismo.longitud });
  };

  // Función mejorada para filtrar los sismos
  const handleBuscar = () => {
    fetch("http://localhost:9090/inicio")
      .then((response) => {
        if (!response.ok) throw new Error("Error en la respuesta del servidor");
        return response.json();
      })
      .then((data) => {
        // Filtrar sismos según los criterios
        let sismosFiltrados = data;
        
        // Filtrar por fecha si hay un valor
        if (fechaFiltro) {
          sismosFiltrados = sismosFiltrados.filter(sismo => 
            sismo.fecha === fechaFiltro
          );
        }
        
        // Filtrar por magnitud si hay un valor
        if (magnitudFiltro) {
          sismosFiltrados = sismosFiltrados.filter(sismo => 
            sismo.magnitud >= parseFloat(magnitudFiltro)
          );
        }
        
        setSismos(sismosFiltrados);
        
        // Mostrar mensaje si no hay resultados
        if (sismosFiltrados.length === 0) {
          setNoResults(true);
        } else {
          setNoResults(false);
        }
      })
      .catch((error) => {
        console.error("Error al filtrar datos:", error);
        // Mostrar mensaje de error al usuario
      });
  };

  // Función para limpiar los filtros
  const handleLimpiar = () => {
    setFechaFiltro("");
    setMagnitudFiltro("");
    setNoResults(false);
    
    fetch("http://localhost:9090/inicio")
      .then(response => response.json())
      .then(data => {
        setSismos(data);
      })
      .catch(error => {
        console.error("Error al restablecer datos:", error);
      });
  };

  return (
    <div className={`container ${theme}`}>
      {/* Switch del Tema */}
      <div className="theme-switch-container">
        <label className="switch">
          <input
            type="checkbox"
            onChange={toggleTheme}
            checked={theme === "dark"}
          />
          <span className="slider round"></span>
        </label>
      </div>

      {/* Cuadro de búsqueda */}
      <div className="search-container">
        <input
          type="date"
          value={fechaFiltro}
          onChange={(e) => setFechaFiltro(e.target.value)}
          placeholder="Fecha"
          className="search-input"
        />
        <input
          type="number"
          min="0"
          step="0.1"
          value={magnitudFiltro}
          onChange={(e) => setMagnitudFiltro(e.target.value)}
          placeholder="Magnitud mínima"
          className="search-input"
        />
        <div className="button-group">
          <button onClick={handleBuscar} className="search-button">
            Buscar
          </button>
          <button onClick={handleLimpiar} className="search-button clear-button">
            Limpiar
          </button>
        </div>
        {noResults && (
          <p className="no-results">No se encontraron sismos con estos criterios</p>
        )}
      </div>

      {/* Contenedor del Mapa */}
      <div className="map-container">
        <MapaMexico coordenadas={coordenadas} theme={theme} />
      </div>

      {/* Menú lateral */}
      <div className={`sidebar ${menuVisible ? "visible" : ""}`}>
        <button className="close-btn" onClick={() => setMenuVisible(false)}>
          &times;
        </button>
        <h2>Menú</h2>
        <ul>
          <li>
            <a href="#sismos">Sismos Recientes</a>
          </li>
        </ul>
        <div className="content">
          <h2 id="sismos">Sismos Recientes</h2>
          <ul className="sismos-list">
            {sismos.map((sismo) => (
              <li
                key={sismo.identificador}
                className={`sismo-item ${
                  sismoSeleccionado === sismo ? "activo" : ""
                }`}
                onClick={() => handleSismoClick(sismo)}
              >
                <strong>{sismo.referenciaLocalizacion}</strong> - Magnitud:{" "}
                {sismo.magnitud}
              </li>
            ))}
          </ul>
          {sismoSeleccionado && (
            <div className="sismo-info">
              <h3>Detalles del Sismo</h3>
              <p>
                <b>Ubicación:</b> {sismoSeleccionado.referenciaLocalizacion}
              </p>
              <p>
                <b>Magnitud:</b> {sismoSeleccionado.magnitud}
              </p>
              <p>
                <b>Fecha:</b> {sismoSeleccionado.fecha}{" "}
                {sismoSeleccionado.hora}
              </p>
              <p>
                <b>Profundidad:</b> {sismoSeleccionado.profundidad} km
              </p>
              <p>
                <b>Latitud:</b> {sismoSeleccionado.latitud},{" "}
                <b>Longitud:</b> {sismoSeleccionado.longitud}
              </p>
              <p>
                <b>Estatus:</b> {sismoSeleccionado.estatus}
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Botón del menú hamburguesa */}
      <button
        className="menu-btn"
        onClick={() => setMenuVisible(!menuVisible)}
      >
        &#9776;
      </button>
    </div>
  );
}

export default Inicio;
